function CountOpening(brackets: string): int
    reads brackets
    ensures 0 <= CountOpening(brackets) <= |brackets|
{
    var count := 0;
    var i := 0;
    while i < |brackets|
        invariant 0 <= i <= |brackets| && count == CountOpening(brackets[0..i])
    {
        if brackets[i] == '(' {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

function CountClosing(brackets: string): int
    reads brackets
    ensures 0 <= CountClosing(brackets) <= |brackets|
{
    var count := 0;
    var i := 0;
    while i < |brackets|
        invariant 0 <= i <= |brackets| && count == CountClosing(brackets[0..i])
    {
        if brackets[i] == ')' {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

function NoUnmatchedOpening(brackets: string): bool
    reads brackets
{
    var balance := 0;
    var i := 0;
    while i < |brackets|
        invariant 0 <= i <= |brackets| && balance >= 0
    {
        if brackets[i] == '(' {
            balance := balance + 1;
        } else if brackets[i] == ')' {
            balance := balance - 1;
        }
        i := i + 1;
    }
    return balance == 0;
}
